import java.util.Scanner;

public class Main {
    static long[] f = new long[181];
    static long n;
    static long min_total;
    static long abs_value(long x) {
        return x < 0 ? -x : x;
    }

    static void explore(int level, long total) {
        if (n == 0) {
            min_total = Math.min(min_total, total);
            return;
        }
        if (level == 0) return;

        for (int i = -10; i <= 10; ++i) {
            long delta = i * f[level];
            if (n + delta > 0) {
                n += delta;
                explore(level - 1, total + abs_value(i) * level);
                n -= delta;
                break;
            }
        }
        for (int i = -10; i <= 10; ++i) {
            long delta = i * f[level];
            if (n + delta == 0) {
                n += delta;
                explore(level - 1, total + abs_value(i) * level);
                n -= delta;
                break;
            }
        }
        for (int i = 10; i >= -10; --i) {
            long delta = i * f[level];
            if (n + delta < 0) {
                n += delta;
                explore(level - 1, total + abs_value(i) * level);
                n -= delta;
                break;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        f[1] = 1;
        for (int i = 2; i <= 16; ++i) {
            f[i] = f[i - 1] * 10 + 1;
        }
        min_total = Long.MAX_VALUE;
        explore(16, 0);
        System.out.println(min_total);
